if (e.ChangedButton == MouseButton.Left)
            {
                Focus();
                Keyboard.Focus(this);
                CaptureMouse();
                if (Tool != null)
                {
                    Circuit.Coord at = SnapToGrid(e.GetPosition(root));
                    if (e.ClickCount == 2)
                        Tool.MouseDoubleClick(at);
                    else
                        Tool.MouseDown(at);
                }
                e.Handled = true;
            }
            else if (e.ChangedButton == MouseButton.Middle)
            {
                Focus();
                Keyboard.Focus(this);
                CaptureMouse();
                e.Handled = true;
            }
            else if (e.ChangedButton == MouseButton.Right)
            {
                ReleaseMouseCapture();
                if (Tool != null)
                    Tool.Cancel();
                e.Handled = true;
            }

