public SignalDisplay()
        {
            refreshTimer = new System.Timers.Timer()
            {
                Interval = 16,  // 60 Hz
                AutoReset = true,
                Enabled = true,
            };
            refreshTimer.Elapsed +=
                (o, e) => Dispatcher.InvokeAsync(() => InvalidateVisual(), System.Windows.Threading.DispatcherPriority.ApplicationIdle);
            refreshTimer.Start();
        }

